"""Package a local, sound-enabled user review. No publishing."""
import argparse,json,shutil,hashlib
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);a=p.parse_args()
b=Path(__file__).resolve().parents[1];out=a.directory
if not (out/'preview-safe.mp4').is_file():raise SystemExit('Complete the mastered review first.')
shutil.copy2(b.parent/'captions.bn.srt',out/'captions.bn.srt')
shutil.copy2(b.parent/'recorded-script.bn.txt',out/'recorded-script.bn.txt')
